<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\MediaItem;use App\Models\SiteSetting;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;use Illuminate\View\View;
class MediaItemController extends Controller {public function index():View{return view('admin.media.index',['items'=>MediaItem::orderBy('sort_order')->latest('published_at')->paginate(20),'settings'=>SiteSetting::firstOrCreate([])]);}public function settings(Request $r):RedirectResponse{SiteSetting::firstOrCreate([])->update($r->validate(['media_page_title'=>['required','string','max:255'],'media_section_title'=>['required','string','max:255'],'media_button_text'=>['required','string','max:100']]));return back()->with('status','Media page settings updated successfully.');}public function store(Request $r):RedirectResponse{$data=$this->validated($r,true);$data['image']=$r->file('image')->store('media','public');$data['is_active']=$r->boolean('is_active');MediaItem::create($data);return back()->with('status','Media item added successfully.');}public function update(Request $r,MediaItem $medium):RedirectResponse{$data=$this->validated($r);if($r->hasFile('image')){if(!str_starts_with($medium->image,'http'))Storage::disk('public')->delete($medium->image);$data['image']=$r->file('image')->store('media','public');}$data['is_active']=$r->boolean('is_active');$medium->update($data);return back()->with('status','Media item updated successfully.');}public function destroy(MediaItem $medium):RedirectResponse{if(!str_starts_with($medium->image,'http'))Storage::disk('public')->delete($medium->image);$medium->delete();return back()->with('status','Media item deleted successfully.');}private function validated(Request $r,bool $create=false):array{return $r->validate(['title'=>['required','string','max:255'],'image'=>[$create?'required':'nullable','image','max:4096'],'url'=>['required','url','max:1000'],'published_at'=>['nullable','date'],'sort_order'=>['nullable','integer','min:0']]);}}
